 private void check(boolean b,String why){if(!b)throw new AssertionError(why);}
 private void await(BooleanSupplier b,String why,long ms){long end=SystemClock.elapsedRealtime()+ms;while(SystemClock.elapsedRealtime()<end){if(b.getAsBoolean())return;SystemClock.sleep(80);}throw new AssertionError(why);}
 private <T> T ui(java.util.concurrent.Callable<T> task){AtomicReference<T> value=new AtomicReference<>();AtomicReference<Throwable> failed=new AtomicReference<>();runOnMainSync(()->{try{value.set(task.call());}catch(Throwable t){failed.set(t);}});if(failed.get()!=null)throw new AssertionError("UI action",failed.get());return value.get();}
