 private AuthFixtureActivity.CancelTrace verifyCancel(AuthFixtureActivity a){AuthFixtureActivity.CancelTrace trace=ui(a::lastCancel);check(trace!=null,"missing atomic cancel trace");report.append(trace).append('\n');AuthFixtureActivity.State b=trace.before,c=trace.after;check(b.generation==c.generation&&c.keyClosed,"cancel ownership/cleanup");
  boolean terminal=b.status.equals("CANCELLED")||b.status.equals("BACKGROUND")||b.status.equals("REJECTED")||b.status.equals("FAILED");
  if(terminal)check(c.status.equals(b.status)&&c.failure.equals(b.failure)&&c.nativeStatus==b.nativeStatus&&c.reason.equals(b.reason)&&c.closes==b.closes,"cancel erased terminal cause or closed twice");
  else if(b.status.equals("NONE"))check(c.status.equals("NONE")&&c.closes==b.closes,"cancel without owner");
  else check(b.foreground&&c.status.equals("CANCELLED")&&c.failure.equals("NONE")&&c.stage==6&&c.closes==b.closes+1,"live cancel did not close exactly once");return trace;
 }
